    add_32 add_IF(.a(PC_IF),.b(32'd4),.c(PC_4_IF));

    MUX2T1_32 mux_IF(.I0(PC_4_IF),.I1(PC_jump_FU),.s(1'b0),.o(next_PC_IF)); // TODO: implement mux select

    ROM_D inst_rom(.a(PC_IF[10:2]),.spo(inst_IF));


