    RS #(.FU(`FU_ALU), .num(3)) rs_alu(
        .clk(debug_clk),
	    .rst(rst),

		.selected(ALU_use),
	    .free_rs(rs_num_rd_ALU),
	    .op(op_IS),
		.Qj(8'b0), // TODO: implement
		.Qk(8'b0), // TODO: implement
		.Vj(32'b0), // TODO: implement
		.Vk(32'b0), // TODO: implement
		.A(0),
		.pc_IS(PC_IS),

		.en_FU(FU_ALU_EN),
	    .vj(ALU_src1), // TODO: implement
	    .vk(ALU_src2), // TODO: implement
		.op_out(ALU_op),
		.A_o(/* unused */),
		.pc_FU(/* unused */),


		.cdb_rs_rd(ALU_rs_rd),
		.cdb_rs_num(cdb_rs_num),
		.cdb_data(cdb_data),


		.pc_debug(ALU_pc)
    );


    // For memory access instrs, to ensure in-order memory access:
    //  if u use RS defined in this project, alloc one entry only
    //  u can also implement load store queue
    //  BTW, u can also implement out-of-order memory access (orz 


    // FU, just those in lab5
    FU_ALU alu(.clk(debug_clk),.EN(FU_ALU_EN),.finish(FU_ALU_finish),
        .ALUControl(4'b0),.ALUA(32'b0),.ALUB(32'b0),.res(ALUout_FU), // TODO: implement — connect ALU inputs
        .zero(),.overflow());

    FU_mem mem(.clk(debug_clk),.EN(FU_mem_EN),.finish(FU_mem_finish),
        .mem_w(1'b0),.bhw(3'b0),.rs1_data(32'b0),.rs2_data(32'b0), // TODO: implement — connect MEM inputs
        .imm(32'b0),.mem_data(mem_data_FU));

    FU_mul mu(.clk(debug_clk),.EN(FU_mul_EN),.finish(FU_mul_finish),
        .A(32'b0),.B(32'b0),.res(mulres_FU)); // TODO: implement — connect MUL inputs

    FU_div du(.clk(debug_clk),.EN(FU_div_EN),.finish(FU_div_finish),
        .A(32'b0),.B(32'b0),.res(divres_FU)); // TODO: implement — connect DIV inputs

    FU_jump ju(.clk(debug_clk),.EN(FU_jump_EN),.finish(FU_jump_finish),
        .JALR(1'b0),.cmp_ctrl(4'b0),.rs1_data(32'b0),.rs2_data(32'b0), // TODO: implement — connect JUMP inputs
        .imm(32'b0),.PC(32'b0),.PC_jump(PC_jump_FU),.PC_wb(PC_wb_FU),.is_jump(is_jump_FU));


    // CDB broadcast 
    reg [5:1] done_record; // similar to lab5, when multi-FU finish, we need to choose one and delay others 
    wire [31:0]cdb_pc;  // for debug

    assign cdb_data = 32'b0; // TODO: implement — CDB data broadcast
    assign cdb_rs_num = 8'b0; // TODO: implement — CDB RS number broadcast
    assign cdb_pc = 32'b0; // TODO: implement — CDB PC for debug


    assign wb_addr = cdb_pc;
    assign wb_data = cdb_data;

    always @(posedge debug_clk) begin
        if (rst) begin
            clk_counter <= 0;
        end else begin
            clk_counter <= clk_counter + 32'd1;
        end
    end



endmodule

