#!/usr/bin/env python3
"""Compare a WB trace (lines: 'WB <pc> <rd> <val>') against an expectation file.

Usage: check_trace.py <expect.txt> <trace.txt>

The trace may contain the program executing more than once (the test programs loop);
only the first occurrence of each PC is used.
"""
import sys


def load_expect(path):
    exp = []
    with open(path) as f:
        for line in f:
            line = line.split('#')[0].strip()
            if not line:
                continue
            pc, rd, val = line.split()
            exp.append((int(pc, 16), int(rd), int(val, 16)))
    return exp


def load_trace(path):
    seen = {}
    order = []
    with open(path) as f:
        for line in f:
            parts = line.split()
            if len(parts) != 4 or parts[0] != 'WB':
                continue
            try:
                pc, rd, val = int(parts[1], 16), int(parts[2]), int(parts[3], 16)
            except ValueError:
                continue
            if pc not in seen:
                seen[pc] = (rd, val)
                order.append(pc)
    return seen, order


def main():
    exp = load_expect(sys.argv[1])
    seen, order = load_trace(sys.argv[2])
    bad = 0
    for pc, rd, val in exp:
        got = seen.get(pc)
        if got is None:
            print('MISS  pc=%03x expected x%-2d = %08x  (no write-back seen)' % (pc, rd, val))
            bad += 1
        elif got != (rd, val):
            print('WRONG pc=%03x expected x%-2d = %08x  got x%-2d = %08x'
                  % (pc, rd, val, got[0], got[1]))
            bad += 1
        else:
            print('ok    pc=%03x x%-2d = %08x' % (pc, rd, val))
    expected_pcs = set(p for p, _, _ in exp)
    extra = [p for p in order if p not in expected_pcs]
    if extra:
        print('NOTE  unexpected register writes at PCs: %s'
              % ' '.join('%03x' % p for p in extra[:20]))
        bad += len(extra)
    print('\n%d/%d expected write-backs correct; %d problems' % (len(exp) - bad, len(exp), bad))
    sys.exit(1 if bad else 0)


main()

