    wire [31:0] debug_data, pc, inst, mem_addr, mem_data;

    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'd0), .debug_data(debug_data),
        .clk(clk), .rst(rst), .interrupter(1'b0),
        .pc(pc), .inst(inst), .mem_addr(mem_addr), .mem_data(mem_data)
    );

    initial begin
        clk = 0;
        rst = 1;
        #4 rst = 0;
    end
    always #1 clk = ~clk;

    // sample in the middle of the cycle, after the pipeline latches settled
    always @(negedge clk) begin
        if (!rst && core.RegWrite_WB === 1'b1 && core.rd_WB !== 5'd0)
            $display("WB %08x %0d %08x", core.PC_WB, core.rd_WB, core.wt_data_WB);
    end

    initial begin
        #1200 $finish;
    end
endmodule

